125:                         workerConnection.State == ConnectionState.Open)
126:                     {
127:                         workerConnection.DefaultTimeout = defaultTimeout;
128:                         openedConnection = workerConnection;
129:                         workerConnection = null;
130:                     }
131:                 }
132:                 catch (Exception exception)
133:                 {
134:                     failure = exception;
135:                 }
136:                 finally
137:                 {
138:                     if (workerConnection is not null &&
139:                         cancellationState.RequestedKind != OpenCancellationKind.None)
140:                     {
141:                         CloseAfterInterruptedOpen(workerConnection);
142:                     }
143: 
144:                     try
145:                     {
146:                         dataSourceLease?.Dispose();
147:                     }
148:                     catch (Exception exception)
149:                     {
150:                         failure ??= exception;
151:                     }
152: 
153:                     try
154:                     {
155:                         workerConnection?.Dispose();
156:                     }
157:                     catch (Exception exception)
158:                     {
159:                         failure ??= exception;
160:                     }
161: 
162:                     workerOutcome.TrySetResult(new SqliteOpenOutcome(openedConnection, failure));
163:                     Volatile.Read(ref s_beforeWorkerExit)?.Invoke();
164:                 }
165:             })
166:         {
167:             IsBackground = true,
168:             Name = "McpSqliteIsolatedOpen",
169:         };
170: 
171:         Interlocked.Increment(ref s_activeWorkerCount);
172:         try
173:         {
174:             thread.Start();
175:         }
176:         catch
177:         {
178:             Interlocked.Decrement(ref s_activeWorkerCount);
179:             cancellationState.Complete();
180:             throw;
181:         }
182: 
183:         Interlocked.Increment(ref s_workerInvocationCount);
184:         _ = TrackIsolatedWorkerUntilActuallyGoneAsync(
185:             thread,
186:             workerOutcome.Task,
187:             cancellationState,
188:             completion);
189: 
190:         var winner = await Task.WhenAny(
191:                 completion.Task,
192:                 cancellationSignal.Task,
193:                 timeoutSignal.Task)
194:             .ConfigureAwait(false);
195:         if (!ReferenceEquals(winner, completion.Task))
196:         {
197:             var cleanupDeadline = Task.Delay(s_nativeCleanupTimeout);
198:             while (!completion.Task.IsCompleted && !cleanupDeadline.IsCompleted)
199:             {
200:                 cancellationState.TryCancelNativeWork();
201:                 await Task.WhenAny(
202:                         completion.Task,
203:                         cleanupDeadline,
204:                         Task.Delay(TimeSpan.FromMilliseconds(10)))
205:                     .ConfigureAwait(false);
206:             }
207:         }
208: 
209:         var cancellationKind = cancellationState.RequestedKind;
210:         if (!completion.Task.IsCompleted)
211:         {
212:             ThrowRequestedCancellation(
213:                 cancellationKind,
214:                 timeout,
215:                 cancellationToken,
216:                 failure: null);
217:         }
218: 
219:         var outcome = await completion.Task.ConfigureAwait(false);
220:         if (outcome.Failure is null && outcome.Connection is not null)
221:         {
222:             if (cancellationKind != OpenCancellationKind.None)
223:             {
224:                 outcome.Connection.Dispose();
225:                 ThrowRequestedCancellation(
226:                     cancellationKind,
227:                     timeout,
228:                     cancellationToken,
229:                     failure: null);
230:             }
231: 
232:             return outcome.Connection;
233:         }
234: 
235:         if (outcome.Failure is not null &&
236:             IsGenuineCancellation(outcome.Failure, cancellationState, cancellationToken) &&
237:             cancellationKind != OpenCancellationKind.None)
238:         {
239:             ThrowRequestedCancellation(
240:                 cancellationKind,
241:                 timeout,
242:                 cancellationToken,
243:                 outcome.Failure);
244:         }
245: 
246:         if (outcome.Failure is not null)
247:             ExceptionDispatchInfo.Capture(outcome.Failure).Throw();
248: 
249:         ThrowRequestedCancellation(
250:             cancellationKind,
251:             timeout,
252:             cancellationToken,
253:             failure: null);
254:         throw new InvalidOperationException("SQLite isolated opening produced no connection.");
255:     }
