257:     /// <summary>
258:     /// Retains truthful worker accounting and disposes an unpublished successful clone when
259:     /// cancellation won before the worker's real exit.
260:     /// </summary>
261:     private static async Task TrackIsolatedWorkerUntilActuallyGoneAsync(
262:         Thread thread,
263:         Task<SqliteOpenOutcome> workerOutcome,
264:         OpenCancellationState cancellationState,
265:         TaskCompletionSource<SqliteOpenOutcome> completion)
266:     {
267:         while (thread.IsAlive)
268:             await Task.Delay(TimeSpan.FromMilliseconds(5)).ConfigureAwait(false);
269: 
270:         var outcome = await workerOutcome.ConfigureAwait(false);
271:         if (cancellationState.RequestedKind != OpenCancellationKind.None &&
272:             outcome.Connection is not null)
273:         {
274:             outcome.Connection.Dispose();
275:             outcome = outcome with { Connection = null };
276:         }
277: 
278:         cancellationState.Complete();
279:         Interlocked.Decrement(ref s_activeWorkerCount);
280:         completion.TrySetResult(outcome);
281:     }
