300:     private static void ThrowRequestedCancellation(
301:         OpenCancellationKind cancellationKind,
302:         TimeSpan timeout,
303:         CancellationToken cancellationToken,
304:         Exception? failure)
305:     {
306:         if (cancellationKind == OpenCancellationKind.Caller)
307:         {
308:             throw new OperationCanceledException(
309:                 "SQLite connection opening was cancelled by the caller.",
310:                 failure,
311:                 cancellationToken);
312:         }
313: 
314:         if (cancellationKind == OpenCancellationKind.Timeout)
315:         {
316:             throw new TimeoutException(
317:                 $"SQLite connection opening exceeded the finite timeout of {timeout}.",
318:                 failure);
319:         }
320: 
321:         throw new InvalidOperationException(
322:             "SQLite bounded opening lost its cancellation classification.",
323:             failure);
324:     }
