326:     private static void ValidateBoundedDataSource(
327:         SqliteConnection connection,
328:         bool invokeBoundaryHook = true)
329:     {
330:         var options = new SqliteConnectionStringBuilder(connection.ConnectionString);
331:         var dataSource = options.DataSource;
332:         if (options.Mode == SqliteOpenMode.Memory ||
333:             string.IsNullOrWhiteSpace(dataSource) ||
334:             string.Equals(dataSource, ":memory:", StringComparison.OrdinalIgnoreCase) ||
335:             (dataSource.StartsWith("file:", StringComparison.OrdinalIgnoreCase) &&
336:              dataSource.Contains("mode=memory", StringComparison.OrdinalIgnoreCase)))
337:         {
338:             return;
339:         }
340: 
341:         if (dataSource.StartsWith("file:", StringComparison.OrdinalIgnoreCase))
342:         {
343:             var withoutScheme = dataSource["file:".Length..];
344:             var queryIndex = withoutScheme.IndexOf('?');
345:             if (queryIndex >= 0)
346:                 withoutScheme = withoutScheme[..queryIndex];
347: 
348:             dataSource = Uri.UnescapeDataString(withoutScheme);
349:         }
350: 
351:         var lexicalPath = Path.GetFullPath(dataSource);
352:         _ = BoundedFileSystemPolicy.EnsureLexicalPathSupportsBoundedNativeIo(
353:             lexicalPath,
354:             "SQLite connection opening");
355:         if (invokeBoundaryHook)
356:             Volatile.Read(ref s_beforeDataSourcePhysicalResolution)?.Invoke();
357: 
358:         var physicalCandidate =
359:             BoundedFileSystemPolicy.EnsureLexicalPathSupportsBoundedNativeIo(
360:                 lexicalPath,
361:                 "SQLite connection opening");
362:         if (!OperatingSystem.IsLinux())
363:             return;
364: 
365:         var physicalPath = LinuxPhysicalPathResolver.TryResolveWithNonexistentSuffix(
366:                 physicalCandidate)
367:             ?? throw new IOException(
368:                 $"SQLite connection opening could not resolve '{physicalCandidate}'.");
369:         BoundedFileSystemPolicy.EnsurePathSupportsBoundedNativeIo(
370:             physicalPath,
371:             "SQLite connection opening");
372:     }
