439:     /// <summary>
440:     /// Accesses Microsoft.Data.Sqlite's state field so the public connection-string setter can
441:     /// restore both visible identity and pool identity after a successful pinned open. The
442:     /// connection is exclusively owned by this worker until completion is published.
443:     /// </summary>
444:     [UnsafeAccessor(UnsafeAccessorKind.Field, Name = "_state")]
445:     private static extern ref ConnectionState GetConnectionStateBackingField(
446:         SqliteConnection connection);
447: 
448:     /// <summary>
449:     /// Owns a Linux descriptor only through the native SQLite open and restores the connection's
450:     /// public identity and future-open pool identity without changing the active native connection.
451:     /// </summary>
452:     private sealed class PinnedSqliteDataSourceLease : IDisposable
453:     {
454:         private readonly SqliteConnection _connection;
455:         private readonly string _originalConnectionString;
456:         private IDisposable? _handle;
457:         private int _completed;
458: 
459:         internal PinnedSqliteDataSourceLease(
460:             SqliteConnection connection,
461:             string originalConnectionString,
462:             IDisposable handle)
463:         {
464:             _connection = connection;
465:             _originalConnectionString = originalConnectionString;
466:             _handle = handle;
467:         }
468: 
469:         /// <summary>
470:         /// Releases the pin after SQLite owns its native handle, prevents descriptor-keyed pooling,
471:         /// and restores the exact public connection string before the caller observes completion.
472:         /// </summary>
473:         internal void CompleteOpen()
474:         {
475:             DisposeHandle();
476:             try
477:             {
478:                 // A descriptor number can be reused for another file. Mark this descriptor-keyed
479:                 // pool stale before the inner connection can ever be returned to it.
480:                 SqliteConnection.ClearPool(_connection);
481:             }
482:             finally
483:             {
484:                 RestoreConnectionIdentity();
485:                 Volatile.Write(ref _completed, 1);
486:             }
487:         }
488: 
489:         /// <inheritdoc />
490:         public void Dispose()
491:         {
492:             DisposeHandle();
493:             if (Volatile.Read(ref _completed) != 0)
494:                 return;
495: 
496:             if (_connection.State == ConnectionState.Closed)
497:             {
498:                 RestoreClosedConnectionString();
499:                 return;
500:             }
501: 
502:             try
503:             {
504:                 SqliteConnection.ClearPool(_connection);
505:             }
506:             finally
507:             {
508:                 RestoreConnectionIdentity();
509:             }
510:         }
511: 
512:         /// <summary>Restores both the public string and pool group while the connection is closed.</summary>
513:         private void RestoreClosedConnectionString()
514:         {
515:             try
516:             {
517:                 _connection.ConnectionString = _originalConnectionString;
518:             }
519:             catch (ObjectDisposedException)
520:             {
521:                 // A disposed connection has no reusable public connection string to restore.
522:             }
523:         }
524: 
525:         /// <summary>
526:         /// Restores the public string and future-open pool group while retaining the already-open
527:         /// inner connection. The owning worker has exclusive access until completion is published.
528:         /// </summary>
529:         private void RestoreConnectionIdentity()
530:         {
531:             ref var state = ref GetConnectionStateBackingField(_connection);
532:             var openState = state;
533:             state = ConnectionState.Closed;
534:             try
535:             {
536:                 _connection.ConnectionString = _originalConnectionString;
537:             }
538:             finally
539:             {
540:                 state = openState;
541:             }
542:         }
543: 
544:         /// <summary>Releases the exact pinned descriptor at most once.</summary>
545:         private void DisposeHandle() =>
546:             Interlocked.Exchange(ref _handle, null)?.Dispose();
547:     }
