550:     private static void CloseAfterInterruptedOpen(SqliteConnection connection)
551:     {
552:         try
553:         {
554:             if (connection.State != ConnectionState.Closed)
555:                 connection.Close();
556:         }
557:         catch (Exception)
558:         {
559:             // A concurrent close or disposal already owns cleanup.
560:         }
561:     }
