563:     private static bool IsGenuineCancellation(
564:         Exception failure,
565:         OpenCancellationState cancellationState,
566:         CancellationToken callerToken)
567:     {
568:         if (failure is OperationCanceledException operationCanceledException)
569:         {
570:             if (cancellationState.RequestedKind == OpenCancellationKind.Caller &&
571:                 callerToken.IsCancellationRequested &&
572:                 operationCanceledException.CancellationToken == callerToken)
573:             {
574:                 return true;
575:             }
576: 
577:             return cancellationState.SynchronousIoCancellationIssued &&
578:                    (operationCanceledException.CancellationToken == default ||
579:                     IsWindowsOperationAborted(operationCanceledException.InnerException));
580:         }
581: 
582:         return cancellationState.SynchronousIoCancellationIssued &&
583:                IsWindowsOperationAborted(failure);
584:     }
585: 
586:     private static bool IsWindowsOperationAborted(Exception? exception) =>
587:         OperatingSystem.IsWindows() &&
588:         exception is IOException ioException &&
589:         (ioException.HResult & 0xFFFF) == ErrorOperationAborted;
