591:     /// <summary>Cancellation origin retained separately so timeouts never impersonate caller cancellation.</summary>
592:     private enum OpenCancellationKind
593:     {
594:         None,
595:         Caller,
596:         Timeout,
597:     }
598: 
599:     /// <summary>Coordinates finite Windows native-I/O cancellation and worker lifecycle state.</summary>
600:     private sealed class OpenCancellationState
601:     {
602:         private readonly object _sync = new();
603:         private uint _threadId;
604:         private int _requestedKind;
605:         private int _synchronousIoCancellationIssued;
606:         private bool _completed;
607: 
608:         internal OpenCancellationKind RequestedKind =>
609:             (OpenCancellationKind)Volatile.Read(ref _requestedKind);
610: 
611:         internal bool SynchronousIoCancellationIssued =>
612:             Volatile.Read(ref _synchronousIoCancellationIssued) != 0;
613: 
614:         internal void AttachThread(uint threadId)
615:         {
616:             lock (_sync)
617:             {
618:                 if (_completed)
619:                     return;
620:                 _threadId = threadId;
621:             }
622: 
623:             if (RequestedKind != OpenCancellationKind.None)
624:                 TryCancelNativeWork();
625:         }
626: 
627:         internal void Request(OpenCancellationKind kind)
628:         {
629:             lock (_sync)
630:             {
631:                 if (_completed)
632:                     return;
633:                 _ = Interlocked.CompareExchange(
634:                     ref _requestedKind,
635:                     (int)kind,
636:                     (int)OpenCancellationKind.None);
637:             }
638:         }
639: 
640:         internal void Complete()
641:         {
642:             lock (_sync)
643:             {
644:                 _completed = true;
645:                 _threadId = 0;
646:             }
647:         }
648: 
649:         internal void TryCancelNativeWork()
650:         {
651:             uint threadId;
652:             lock (_sync)
653:             {
654:                 if (_completed)
655:                     return;
656:                 threadId = _threadId;
657:             }
658: 
659:             if (OperatingSystem.IsWindows() && threadId != 0)
660:             {
661:                 var threadHandle = OpenThread(ThreadTerminate, inheritHandle: false, threadId);
662:                 if (threadHandle != IntPtr.Zero)
663:                 {
664:                     try
665:                     {
666:                         if (CancelSynchronousIo(threadHandle))
667:                             Volatile.Write(ref _synchronousIoCancellationIssued, 1);
668:                     }
669:                     finally
670:                     {
671:                         _ = CloseHandle(threadHandle);
672:                     }
673:                 }
674:             }
675: 
676: 
677:         }
678:     }
