682:     private static extern uint GetCurrentThreadId();
683: 
684:     [DllImport("kernel32.dll", SetLastError = true)]
685:     private static extern IntPtr OpenThread(
686:         uint desiredAccess,
687:         [MarshalAs(UnmanagedType.Bool)] bool inheritHandle,
688:         uint threadId);
689: 
690:     [DllImport("kernel32.dll", SetLastError = true)]
691:     [return: MarshalAs(UnmanagedType.Bool)]
692:     private static extern bool CancelSynchronousIo(IntPtr threadHandle);
693: 
694:     [DllImport("kernel32.dll", SetLastError = true)]
695:     [return: MarshalAs(UnmanagedType.Bool)]
696:     private static extern bool CloseHandle(IntPtr handle);
697: }

