  571:         private bool DeleteContainedEntry(string relativePath, bool directory)
  572:         {
  573:             ThrowIfDisposed();
  574:             var relative = NormalizeRelativePath(relativePath);
  575:             if (string.Equals(relative, ".", StringComparison.Ordinal))
  576:                 throw new IOException("The requirements export root cannot be deleted.");
  577: 
  578:             if (OperatingSystem.IsWindows())
  579:             {
  580:                 return DeleteWindowsEntry(
  581:                     RootPath,
  582:                     ResolvePath(relative),
  583:                     directory,
  584:                     _rootHandle);
  585:             }
  586: 
  587:             if (!OperatingSystem.IsLinux())
  588:             {
  589:                 throw new PlatformNotSupportedException(
  590:                     "Same-object contained deletion is implemented for Windows and Linux.");
  591:             }
  592: 
  593:             // unlinkat has no RESOLVE_IN_ROOT equivalent. A pre-opened nested parent could be
  594:             // renamed outside the root between validation and mutation, so only a leaf directly
  595:             // beneath the pinned root is safe to delete. Reject nested cleanup before mutation.
  596:             if (relative.Contains('/'))
  597:             {
  598:                 throw new NotSupportedException(
  599:                     $"Linux requirements export cleanup rejects nested mutation without a kernel-atomic root-relative delete: '{relative}'.");
  600:             }
  601: 
  602:             if (UnlinkAtUnix(
  603:                     _rootHandle.DangerousGetHandle().ToInt32(),
  604:                     relative,
  605:                     directory ? UnixAtRemoveDirectory : 0) == 0)
  606:             {
  607:                 return true;
  608:             }
  609: 
  610:             var error = Marshal.GetLastPInvokeError();
  611:             if (error == UnixNoEntry || (directory && error == UnixDirectoryNotEmpty))
  612:                 return false;
  613:             throw CreateUnixIOException($"Unable to delete contained entry '{relative}'.", error);
  614:         }
