  616:         private void ThrowIfDisposed()
  617:         {
  618:             ObjectDisposedException.ThrowIf(_disposed, this);
  619:         }
  620: 
  621:         private static string NormalizeRelativePath(string relativePath)
  622:         {
  623:             ArgumentException.ThrowIfNullOrWhiteSpace(relativePath);
  624:             var normalized = relativePath.Replace('\\', '/').Trim('/');
  625:             if (normalized.Length == 0 || normalized == ".")
  626:                 return ".";
  627:             var segments = normalized.Split('/', StringSplitOptions.RemoveEmptyEntries);
  628:             if (segments.Any(segment => segment is "." or ".."))
  629:                 throw new IOException($"Invalid root-relative export path: {relativePath}");
  630:             return string.Join('/', segments);
  631:         }
