375:     /// Pins the exact Linux database file with openat2 and routes SQLite through its descriptor path.
376:     /// </summary>
377:     private static PinnedSqliteDataSourceLease? PinLinuxDataSource(
378:         SqliteConnection connection,
379:         string originalConnectionString)
380:     {
381:         if (!OperatingSystem.IsLinux())
382:             return null;
383: 
384:         var options = new SqliteConnectionStringBuilder(connection.ConnectionString);
385:         var dataSource = options.DataSource;
386:         if (options.Mode == SqliteOpenMode.Memory ||
387:             string.IsNullOrWhiteSpace(dataSource) ||
388:             string.Equals(dataSource, ":memory:", StringComparison.OrdinalIgnoreCase) ||
389:             (dataSource.StartsWith("file:", StringComparison.OrdinalIgnoreCase) &&
390:              dataSource.Contains("mode=memory", StringComparison.OrdinalIgnoreCase)))
391:         {
392:             return null;
393:         }
394: 
395:         var isFileUri = dataSource.StartsWith("file:", StringComparison.OrdinalIgnoreCase);
396:         var query = string.Empty;
397:         if (isFileUri)
398:         {
399:             var withoutScheme = dataSource["file:".Length..];
400:             var queryIndex = withoutScheme.IndexOf('?');
401:             if (queryIndex >= 0)
402:             {
403:                 query = withoutScheme[queryIndex..];
404:                 withoutScheme = withoutScheme[..queryIndex];
405:             }
406: 
407:             dataSource = Uri.UnescapeDataString(withoutScheme);
408:         }
409: 
410:         var lexicalPath = Path.GetFullPath(dataSource);
411:         var access = options.Mode == SqliteOpenMode.ReadOnly
412:             ? FileAccess.Read
413:             : FileAccess.ReadWrite;
414:         var create = options.Mode == SqliteOpenMode.ReadWriteCreate;
415:         var handle = LinuxPhysicalPathResolver.OpenFileNoCrossDevice(
416:             lexicalPath,
417:             access,
418:             create,
419:             out _);
420:         try
421:         {
422:             var descriptorPath = $"/proc/self/fd/{handle.DangerousGetHandle()}";
423:             options.DataSource = isFileUri
424:                 ? "file:" + descriptorPath + query
425:                 : descriptorPath;
426:             connection.ConnectionString = options.ToString();
427:             return new PinnedSqliteDataSourceLease(
428:                 connection,
429:                 originalConnectionString,
430:                 handle);
431:         }
432:         catch
433:         {
434:             handle.Dispose();
435:             throw;
436:         }
437:     }
