474:         {
475:             DisposeHandle();
476:             try
477:             {
478:                 // A descriptor number can be reused for another file. Mark this descriptor-keyed
479:                 // pool stale before the inner connection can ever be returned to it.
480:                 SqliteConnection.ClearPool(_connection);
481:             }
482:             finally
483:             {
484:                 RestoreConnectionIdentity();
485:                 Volatile.Write(ref _completed, 1);
486:             }
487:         }
